function gpsQuality(acc){acc=Number(acc);if(!Number.isFinite(acc)||acc<=0)return{label:"GPS yok",level:"none"};if(acc<=8)return{label:`±${Math.round(acc)} m · Çok iyi`,level:"great"};if(acc<=15)return{label:`±${Math.round(acc)} m · İyi`,level:"good"};if(acc<=30)return{label:`±${Math.round(acc)} m · Orta`,level:"medium"};return{label:`±${Math.round(acc)} m · Zayıf`,level:"weak"}}
function packageAgeDays(){const t=Date.parse(data.package?.createdAt||"");return Number.isFinite(t)?Math.floor((Date.now()-t)/86400000):null}
function localDateKey(d=new Date()){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,"0"),day=String(d.getDate()).padStart(2,"0");return `${y}-${m}-${day}`}
function isUnexported(r){const changed=Date.parse(r.saha?.updatedAt||r.saha?.completedAt||"");const exported=Date.parse(r.saha?.lastExportedAt||"");return Number.isFinite(changed)&&(!Number.isFinite(exported)||changed>exported)}
