function photoTypeCounts(r){const c={};for(const m of photoMeta(r)){const t=String(m?.type||"Diğer");c[t]=(c[t]||0)+1}return c}
function requiredPhotoTypes(r){const res=(r.report?.tespitSonucu||[])[0]||"",use=(r.report?.kullanimAmaclari||[])[0]||"";const req=["Genel görünüm"];if(res==="İşgalli"||res==="Kısmen işgalli")req.push("İşgal alanı");if(["Konut","Ticaret","Depo"].includes(use))req.push("Yapı");return [...new Set(req)]}
function evidenceAssessment(r,p){const missing=[],warn=[];const res=(r.report?.tespitSonucu||[])[0]||"";if(!res)missing.push("tespit sonucu");if(geometry(p).length===0)warn.push("KML yok");else if(kmlNeedsReview(p))warn.push("KML kontrol");const gps=r.saha?.gps;if(!gps)missing.push("GPS");else if(Number(gps.accuracy)>30)warn.push("GPS hassasiyeti zayıf");if(!(r.photos||[]).length)missing.push("fotoğraf");else{const counts=photoTypeCounts(r);for(const t of requiredPhotoTypes(r)){if(!counts[t])warn.push(`${t} fotoğrafı yok`)}const q=photoMeta(r).filter(x=>x?.quality?.level==="warn");if(q.length)warn.push(`${q.length} fotoğrafta kalite uyarısı`)}if(!String(r.report?.aciklama||"").trim())warn.push("açıklama yok");if(!String(r.report?.imzaDurumu||"").trim())warn.push("imza durumu yok");if(res==="İşgalli"||res==="Kısmen işgalli"){if(!String(r.report?.kullaniciAdi||"").trim())missing.push("kullanıcı/fuzuli şagil");if(!(r.report?.kullanimAmaclari||[])[0])missing.push("kullanım amacı");if(res==="Kısmen işgalli"&&!String(r.report?.kullanimAlani||"").trim())missing.push("kullanım alanı");if(res==="Kısmen işgalli"&&!occupationGeometry(r).length)warn.push("haritada işgal alanı çizilmedi");const oa=occupationAssessment(occupationGeometry(r),geometry(p));if(occupationGeometry(r).length&&(oa.outside||oa.self||oa.edgeOutside||oa.over))missing.push("işgal alanı çizimi hatalı")}const score=Math.max(0,100-missing.length*18-warn.length*7);return{missing,warn,score,label:missing.length?"Eksik":warn.length?"Kontrol":"Hazır"}}
function completionAssessment(r,p){const base=evidenceAssessment(r,p),critical=[...validate(r)],warn=[...base.warn];for(const x of base.missing)if(!critical.includes(x))critical.push(x);const rv=revisitInfo(r);if(rv)warn.push(`tekrar ziyaret: ${rv.reason||"belirtilmedi"}`);const score=Math.max(0,100-critical.length*20-warn.length*6);return{critical,warn,score,label:critical.length?"Kritik eksik":warn.length?"Kontrol gerekli":"Sahada tamam"}}
async function analyzeImageQuality(src){return new Promise(resolve=>{const im=new Image();im.onload=()=>{try{const c=document.createElement('canvas'),w=64,h=64;c.width=w;c.height=h;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(im,0,0,w,h);const d=x.getImageData(0,0,w,h).data,lum=[];let sum=0;for(let i=0;i<d.length;i+=4){const y=.2126*d[i]+.7152*d[i+1]+.0722*d[i+2];lum.push(y);sum+=y}const mean=sum/lum.length;let edge=0,n=0;for(let yy=1;yy<h;yy++)for(let xx=1;xx<w;xx++){const i=yy*w+xx;edge+=Math.abs(lum[i]-lum[i-1])+Math.abs(lum[i]-lum[i-w]);n+=2}const sharp=edge/Math.max(1,n);let label='Uygun',level='ok';if(mean<38){label='Karanlık olabilir';level='warn'}else if(mean>238){label='Çok aydınlık olabilir';level='warn'}else if(sharp<5.2){label='Bulanık olabilir';level='warn'}resolve({level,label,brightness:Number(mean.toFixed(1)),sharpness:Number(sharp.toFixed(1))})}catch{resolve(null)}};im.onerror=()=>resolve(null);im.src=src})}

function mapFilterSet(){return new Set([...document.querySelectorAll('[data-map-filter]:checked')].map(x=>x.dataset.mapFilter))}
function filteredNeighborhoodProps(){const s=mapFilterSet();return selectedNeighborhoodProps().filter(p=>s.has(propertyState(p)))}
function readinessFor(props){if(!props.length)return{score:0,issues:["Mahalle seçilmedi"]};const issues=[],geom=props.filter(p=>geometry(p).length).length,review=props.filter(kmlNeedsReview).length,age=packageAgeDays();if(geom<props.length)issues.push(`${props.length-geom} KML eksik`);if(review)issues.push(`${review} KML kontrol gerekli`);if(age!=null&&age>30)issues.push(`Saha paketi ${age} günlük`);const score=Math.max(0,Math.round((geom/props.length)*100)-review*2-(age!=null&&age>30?10:0));return{score:Math.min(100,score),issues}}
function renderProgressAndReadiness(){const props=selectedNeighborhoodProps(),st=neighborhoodStats(props),pp=$("#progressPanel"),rp=$("#readinessPanel");if(!pp||!rp)return;const pct=st.total?Math.round(st.done/st.total*100):0;pp.innerHTML=props.length?`<div class="progress-head"><b>Mahalle ilerlemesi</b><span>%${pct}</span></div><div class="progress-track"><i style="width:${pct}%"></i></div><small>${st.done} tamamlandı · ${st.draft} taslak · ${st.todo} yapılmadı · ${st.missing} KML yok</small>`:`<span class="muted">Mahalle seçildiğinde ilerleme burada görünür.</span>`;const rd=readinessFor(props);rp.className=`readiness-panel ${rd.score>=85?'ready':rd.score>=60?'warn':'bad'}`;rp.innerHTML=props.length?`<b>Saha hazırlığı: %${rd.score}</b><small>${rd.issues.length?rd.issues.map(esc).join(' · '):'Veri paketi saha çalışmasına hazır görünüyor.'}</small>`:''}
function renderSyncAlert(){const el=$("#syncAlert");if(!el)return;const n=Object.values(data.records).filter(isUnexported).length;if(n){el.hidden=false;el.innerHTML=`<b>⚠ ${n} kayıt masaüstüne aktarılmadı.</b><span>Saha Sonuçlarını Dışa Aktar ile güvenli kopya oluşturun.</span>`}else el.hidden=true}
function renderRevisitList(){const el=$("#revisitList"),cnt=$("#revisitCount");if(!el)return;const props=data.package?.properties||[],rows=props.map(p=>({p,r:rec(p)})).filter(x=>revisitInfo(x.r));cnt.textContent=`${rows.length} kayıt`;el.innerHTML=rows.length?rows.slice(0,50).map(({p,r})=>`<button type="button" class="mini-row" data-revisit-open="${esc(p.id)}"><b>${esc(p.mahalle)} · ${esc(p.ada)}/${esc(p.parsel)}</b><small>${esc(revisitInfo(r).reason||'Neden belirtilmedi')}</small></button>`).join(''):'<span class="muted">Tekrar ziyaret kaydı yok.</span>';el.querySelectorAll('[data-revisit-open]').forEach(b=>b.onclick=()=>open(b.dataset.revisitOpen))}
function renderDaySummary(){const el=$("#daySummary"),badge=$("#dayBadge");if(!el)return;const day=localDateKey(),rs=Object.values(data.records),today=rs.filter(r=>String(r.saha?.updatedAt||r.saha?.completedAt||'').slice(0,10)===day),completed=today.filter(r=>r.status==='completed').length,revisit=today.filter(r=>revisitInfo(r)).length,photos=today.reduce((n,r)=>n+(r.photos||[]).length,0),unexp=rs.filter(isUnexported).length;badge.textContent=new Date().toLocaleDateString('tr-TR');el.innerHTML=`<div><b>${today.length}</b><span>İşlem gören</span></div><div><b>${completed}</b><span>Tamamlanan</span></div><div><b>${revisit}</b><span>Tekrar gidilecek</span></div><div><b>${photos}</b><span>Fotoğraf</span></div><div><b>${unexp}</b><span>Aktarılmadı</span></div>`}
function assistantChangeCount(p){const r=rec(p),hs=historyEntries(r);if(!hs.length)return 0;if(r.status!=="completed")return compareSnapshots(hs[hs.length-1],currentSnapshot(r)).length;if(hs.length>=2)return compareSnapshots(hs[hs.length-2],hs[hs.length-1]).length;return 0}
