function assistantAnalysis(){const props=selectedNeighborhoodProps(),g=lastGps(),rows=props.map(p=>assistantPriority(p,g)),pending=rows.filter(x=>x.r.status!=="completed"||revisitInfo(x.r)).sort((a,b)=>b.score-a.score),drafts=rows.filter(x=>propertyState(x.p)==="draft"),missingKml=rows.filter(x=>!geometry(x.p).length&&x.r.status!=="completed"),review=rows.filter(x=>kmlNeedsReview(x.p)&&x.r.status!=="completed"),revisits=rows.filter(x=>revisitInfo(x.r)),changed=rows.filter(x=>x.changes>0).sort((a,b)=>b.changes-a.changes),unexported=rows.filter(x=>isUnexported(x.r)),office=rows.reduce((n,x)=>n+x.tasks,0);let evidenceIssues=0;for(const x of drafts){const e=evidenceAssessment(x.r,x.p);if(e.missing.length||e.warn.length)evidenceIssues++}return{props,g,rows,pending,drafts,missingKml,review,revisits,changed,unexported,office,evidenceIssues,top:pending[0]||null}}
