function chooseLiveTarget(force=false){const st=liveState(),g=lastGps(),props=selectedNeighborhoodProps().filter(p=>rec(p).status!=='completed'&&geometry(p).length);if(!props.length){st.targetId=null;return null}if(!force&&st.targetId&&props.some(p=>p.id===st.targetId))return props.find(p=>p.id===st.targetId);let best=null,bd=Infinity;if(g){for(const p of props){const d=distanceToPolygonMeters(g.lon,g.lat,geometry(p));if(d<bd){bd=d;best=p}}}else best=assistantAnalysis().top?.p||props[0];st.targetId=best?.id||null;return best}
