async function startLiveMode(){if(!selectedNeighborhoodProps().length)return toast('Önce ilçe ve mahalle seçin.');const st=liveState();st.active=true;st.startedAt=st.startedAt||new Date().toISOString();st.visited=Number(st.visited||0);chooseLiveTarget(true);await save();try{await startRadar()}catch(e){toast('Canlı mod açıldı; GPS/pusula başlatılamadı: '+e.message)}renderLiveMode();renderAssistant();toast('Canlı saha modu başladı.')}
