function toggleNeighborhoodLive(){if(!window.isSecureContext)return toast("Canlı GPS için uygulamayı HTTPS üzerinden açın.");if(!navigator.geolocation)return toast("Bu cihaz konum erişimini desteklemiyor.");if(neighborhoodWatchId!==null){navigator.geolocation.clearWatch(neighborhoodWatchId);neighborhoodWatchId=null;$("#fullTrackBtn").textContent="● Canlı";toast("Mahalle canlı takibi durduruldu.");return}$("#fullTrackBtn").textContent="■ Durdur";neighborhoodWatchId=navigator.geolocation.watchPosition(async p=>{const g={lat:p.coords.latitude,lon:p.coords.longitude,accuracy:p.coords.accuracy,at:new Date().toISOString()};updateNeighborhoodGpsMarker(g);await save()},e=>toast("Canlı konum alınamadı: "+e.message),geoOptions(true));toast("Mahalle canlı GPS takibi başladı.")}
