async function acquireNeighborhoodGps(showToast=true){if(!window.isSecureContext)throw Error("GPS için uygulamayı HTTPS üzerinden açın.");if(!navigator.geolocation)throw Error("Bu cihaz konum erişimini desteklemiyor.");return new Promise((ok,no)=>navigator.geolocation.getCurrentPosition(async pos=>{const g={lat:pos.coords.latitude,lon:pos.coords.longitude,accuracy:pos.coords.accuracy,at:new Date().toISOString()};updateNeighborhoodGpsMarker(g);await save();if(showToast)toast("Konum mahalle haritasında gösterildi.");ok(g)},e=>no(Error("Konum alınamadı: "+e.message)),geoOptions(false)))}
