function userGps(){const g=current?rec(current).saha?.gps:null;return g&&Number.isFinite(Number(g.lat))&&Number.isFinite(Number(g.lon))?{lat:Number(g.lat),lon:Number(g.lon),accuracy:Number(g.accuracy)||0}:null}
function updateParcelStatus(){const pts=geometry(current),g=userGps(),el=$("#parcelStatus");updateGpsQuality(g);if(!pts.length){el.textContent="Bu taşınmaz için güvenilir KML geometrisi yok.";el.className="parcel-status nogeom";return}if(!g){el.textContent="Parsel sınırı hazır. Konumunuzu almak için ‘Konumumu Güncelle’ye dokunun.";el.className="parcel-status muted";return}const inside=pointInPolygon(g.lon,g.lat,pts),dist=distanceToPolygonMeters(g.lon,g.lat,pts),q=gpsQuality(g.accuracy);el.className=`parcel-status ${inside?"inside":"outside"}`;el.textContent=inside?`✓ KML parsel sınırları içerisindesiniz · ${q.label}`:`Parsel sınırına yaklaşık ${dist<1000?Math.round(dist)+" m":(dist/1000).toFixed(2)+" km"} uzaktasınız · ${q.label}`}
