function render(){const pkg=data.package;const age=packageAgeDays();$("#pkgInfo").textContent=pkg?`${pkg.properties.length} taşınmaz · Paket ${pkg.packageId}${age!=null?` · ${age} günlük`:''}`:"Henüz saha paketi yüklenmedi.";syncNeighborhoodSelectors();const q=$("#search").value.toLocaleUpperCase("tr-TR"),st=$("#status").value;const arr=(pkg?.properties||[]).filter(p=>{const r=rec(p),txt=`${p.mahalle} ${p.ada} ${p.parsel} ${p.ilce}`.toLocaleUpperCase("tr-TR");return(!q||txt.includes(q))&&(st==="all"||r.status===st)});$("#list").innerHTML=arr.map(p=>{const r=rec(p),rv=revisitInfo(r);return`<button class="card item" data-id="${esc(p.id)}"><span><h3>${esc(p.mahalle||"—")} · ${esc(p.ada||"—")} ada ${esc(p.parsel||"—")} parsel</h3><small>${esc(p.ilce||"")} · ${esc(p.yuzolcumu||"—")} m² · ${esc(p.cinsi||"—")}${rv?` · ↩ ${esc(rv.reason||'Tekrar')}`:''}</small></span><span class="chip ${r.status==="completed"?"done":""}">${r.status==="completed"?"Tamamlandı":propertyState(p)==='todo'?"Yapılmadı":"Taslak"}</span></button>`}).join("")||'<div class="card muted">Gösterilecek kayıt yok.</div>';document.querySelectorAll(".item").forEach(b=>b.onclick=()=>open(b.dataset.id));renderSyncAlert();renderRevisitList();renderDaySummary();renderNeighborhoodMap();renderLiveMode();renderAssistant();renderOfflinePrep();renderKmlPrep();renderSmartOps();initBattery();updateStorageInfo()}
async function loadPkg(file){const p=JSON.parse(await file.text());if(p.app!=="METS_SAHA_PAKETI"||!Array.isArray(p.properties))throw Error("Geçerli METS saha paketi değil.");const age=Number.isFinite(Date.parse(p.createdAt))?Math.floor((Date.now()-Date.parse(p.createdAt))/86400000):null;if(age!=null&&age>30&&!confirm(`Bu saha paketi ${age} günlük. TAKPAS/KML verileri güncelliğini yitirmiş olabilir. Yine de yüklensin mi?`))return;const same=data.package?.packageId===p.packageId;if(!same&&data.package&&Object.values(data.records).some(r=>r.status==="completed"||r.saha?.updatedAt)){if(!confirm("Telefonda mevcut saha çalışması var. Yeni pakete geçmeden önce otomatik yedek indirilecek. Devam edilsin mi?"))return;downloadBackup("Otomatik_Oncesi");data={package:null,records:{}}}data.package=p;p.properties.forEach(x=>rec(x));data.meta={...(data.meta||{}),packageLoadedAt:new Date().toISOString()};await save();render();toast(`${p.properties.length} taşınmaz ${same?"güncellendi":"yüklendi"}.`)}

function haversineMeters(aLat,aLon,bLat,bLon){const R=6371000,k=Math.PI/180,dLat=(bLat-aLat)*k,dLon=(bLon-aLon)*k,x=Math.sin(dLat/2)**2+Math.cos(aLat*k)*Math.cos(bLat*k)*Math.sin(dLon/2)**2;return 2*R*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
function bearingDegrees(aLat,aLon,bLat,bLon){const k=Math.PI/180,p1=aLat*k,p2=bLat*k,d=(bLon-aLon)*k,y=Math.sin(d)*Math.cos(p2),x=Math.cos(p1)*Math.sin(p2)-Math.sin(p1)*Math.cos(p2)*Math.cos(d);return(Math.atan2(y,x)/k+360)%360}
function cardinal(deg){const d=['K','KD','D','GD','G','GB','B','KB'];return d[Math.round(((deg%360)+360)%360/45)%8]}
function radarCandidates(g){if(!g)return[];return selectedNeighborhoodProps().filter(p=>rec(p).status!=='completed'&&geometry(p).length).map(p=>{const c=centroid(geometry(p));return{p,c,distance:haversineMeters(g.lat,g.lon,c[1],c[0]),bearing:bearingDegrees(g.lat,g.lon,c[1],c[0])}}).sort((a,b)=>a.distance-b.distance).slice(0,8)}
function signedAngleDiff(target,heading){let d=((target-heading+540)%360)-180;return d}
function lookDirectionLabel(diff){const a=Math.abs(diff);if(a<8)return 'Tam karşıda';if(a<22)return diff<0?'Hafif solda':'Hafif sağda';return diff<0?'Sol önde':'Sağ önde'}
function lookCandidates(g){if(!g||!Number.isFinite(radarHeading))return[];const fov=Number($('#lookFov')?.value||60),range=Number($('#lookRange')?.value||1200);return selectedNeighborhoodProps().filter(p=>geometry(p).length).map(p=>{const c=centroid(geometry(p)),distance=haversineMeters(g.lat,g.lon,c[1],c[0]),bearing=bearingDegrees(g.lat,g.lon,c[1],c[0]),diff=signedAngleDiff(bearing,radarHeading);return{p,c,distance,bearing,diff}}).filter(x=>x.distance<=range&&Math.abs(x.diff)<=fov/2).sort((a,b)=>Math.abs(a.diff)-Math.abs(b.diff)||a.distance-b.distance).slice(0,6)}
function renderLookMode(){const hero=$('#lookHero'),list=$('#lookList'),meta=$('#lookMeta');if(!hero||!list)return;const g=lastGps();if(!g){hero.innerHTML='<b>Konum bekleniyor</b><span>Radar / pusulayı başlatın.</span>';list.innerHTML='';meta.textContent='GPS bekleniyor';return}if(!Number.isFinite(radarHeading)){hero.innerHTML='<b>Pusula bekleniyor</b><span>Telefonun yön sensörüne izin verin.</span>';list.innerHTML='';meta.textContent=`GPS ±${Math.round(g.accuracy||0)} m`;return}const rows=lookCandidates(g),fov=Number($('#lookFov')?.value||60),range=Number($('#lookRange')?.value||1200);meta.textContent=`${Math.round(radarHeading)}° ${cardinal(radarHeading)} · görüş ${fov}° · ${range<1000?range+' m':(range/1000).toFixed(1)+' km'}`;if(!rows.length){hero.innerHTML='<b>Bu yönde kayıtlı parsel görünmüyor</b><span>Telefonu yavaşça sağa/sola çevirin veya görüş açısını artırın.</span>';list.innerHTML='';return}const top=rows[0],status=rec(top.p).status==='completed'?'Tamamlandı':'Tespit bekliyor';hero.innerHTML=`<div class="look-crosshair">＋</div><div><b>${esc(top.p.ada||'—')} ada ${esc(top.p.parsel||'—')} parsel</b><span>${lookDirectionLabel(top.diff)} · ${top.distance<1000?Math.round(top.distance)+' m':(top.distance/1000).toFixed(2)+' km'} · ${status}</span></div><button type="button" data-look-open="${esc(top.p.id)}" class="primary">Aç</button>`;list.innerHTML=rows.slice(1).map(x=>`<button type="button" class="look-row" data-look-open="${esc(x.p.id)}"><b>${esc(x.p.ada||'—')}/${esc(x.p.parsel||'—')}</b><span>${lookDirectionLabel(x.diff)} · ${Math.round(x.bearing)}° · ${x.distance<1000?Math.round(x.distance)+' m':(x.distance/1000).toFixed(2)+' km'}</span></button>`).join('');document.querySelectorAll('[data-look-open]').forEach(b=>b.onclick=()=>open(b.dataset.lookOpen))}
function maybeProximityAlert(g){if(!g||!Number.isFinite(g.lat)||!Number.isFinite(g.lon))return;const props=selectedNeighborhoodProps().filter(p=>rec(p).status!=='completed'&&geometry(p).length);let best=null;for(const p of props){const pts=geometry(p),inside=pointInPolygon(g.lon,g.lat,pts),d=distanceToPolygonMeters(g.lon,g.lat,pts);if(best===null||d<best.d)best={p,d,inside};if((g.accuracy||999)<=25){const prev=proximityState.get(p.id)||{};if(inside&&!prev.inside){try{navigator.vibrate?.([100,70,100])}catch{}toast(`KML sınırına göre ${p.ada||'—'}/${p.parsel||'—'} parsel içerisindesiniz · GPS ±${Math.round(g.accuracy||0)} m`);proximityState.set(p.id,{...prev,inside:true,near:true})}else if(!inside&&d<=100&&!prev.near){try{navigator.vibrate?.(120)}catch{}toast(`${p.ada||'—'}/${p.parsel||'—'} parsel sınırına yaklaşık ${Math.round(d)} m kaldı.`);proximityState.set(p.id,{...prev,near:true,inside:false})}else if(!inside&&d>140&&(prev.near||prev.inside))proximityState.set(p.id,{near:false,inside:false})}}const el=$('#proximityInfo');if(el&&best){const q=gpsQuality(g.accuracy);el.className=`proximity-info ${q.level}`;el.textContent=best.inside?`En yakın hedef: ${best.p.ada||'—'}/${best.p.parsel||'—'} · KML sınırı içinde · ${q.label}`:`En yakın hedef: ${best.p.ada||'—'}/${best.p.parsel||'—'} · sınırına ${Math.round(best.d)} m · ${q.label}`}}
function smartRoute(g){if(!g)return[];let remaining=selectedNeighborhoodProps().filter(p=>rec(p).status!=='completed'&&geometry(p).length).map(p=>({p,c:centroid(geometry(p))}));const route=[];let lat=g.lat,lon=g.lon;while(remaining.length&&route.length<5){let bi=0,bd=Infinity;remaining.forEach((x,i)=>{const d=haversineMeters(lat,lon,x.c[1],x.c[0]);if(d<bd){bd=d;bi=i}});const x=remaining.splice(bi,1)[0];route.push({...x,distance:bd});lat=x.c[1];lon=x.c[0]}return route}
function renderSmartRoute(){const el=$('#smartRoute');if(!el)return;const g=lastGps();if(!g){el.innerHTML='<div class="muted">Konum alındığında en yakın 5 tamamlanmamış parsel sıralanır.</div>';return}const rows=smartRoute(g);el.innerHTML=rows.length?rows.map((x,i)=>`<div class="route-row"><span>${i+1}</span><div><b>${esc(x.p.ada||'—')}/${esc(x.p.parsel||'—')}</b><small>${esc(x.p.mahalle||'')} · önceki duraktan ${x.distance<1000?Math.round(x.distance)+' m':(x.distance/1000).toFixed(2)+' km'}</small></div><button type="button" data-route-open="${esc(x.p.id)}">Aç</button></div>`).join(''):`<div class="muted">Bu mahallede tamamlanmamış KML'li parsel kalmadı.</div>`;el.querySelectorAll('[data-route-open]').forEach(b=>b.onclick=()=>open(b.dataset.routeOpen))}


