async function startCameraAr(){if(!window.isSecureContext)throw Error('Kamera yön görünümü için uygulamayı HTTPS üzerinden açın.');if(!navigator.mediaDevices?.getUserMedia)throw Error('Bu tarayıcı kamera erişimini desteklemiyor.');await startRadar();if(cameraArStream)stopCameraAr(false);cameraArStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});const video=$('#cameraArVideo');video.srcObject=cameraArStream;cameraArActive=true;$('#cameraArOverlay').hidden=false;document.body.classList.add('camera-ar-open');try{await video.play()}catch{}renderCameraAr();toast('Kamera yön görünümü başladı.')}
