function orientationHandler(e){let h=null;if(Number.isFinite(e.webkitCompassHeading))h=e.webkitCompassHeading;else if(Number.isFinite(e.alpha))h=(360-e.alpha)%360;if(Number.isFinite(h)){radarHeading=h;renderRadar();renderLookMode();renderCameraAr()}}
