function renderEntryInfo(){const el=$('#entryInfo');if(!el||!current)return;const ep=rec(current).saha?.entryPoint;if(ep){el.className='entry-info saved';el.textContent=`✓ Giriş noktası kayıtlı · ${Number(ep.lat).toFixed(6)}, ${Number(ep.lon).toFixed(6)} · navigasyon öncelikle buraya gider.`}else{el.className='entry-info muted';el.textContent='Giriş noktası kayıtlı değil. Uygun araç/yaya girişinde konumunuzu kaydedebilirsiniz.'}}

