async function collect(){if(!current)return null;const r=rec(current),f=$("#form");for(const el of f.elements){if(!el.name)continue;if(el.name==="tespitSonucu"||el.name==="kullanimAmaclari")r.report[el.name]=el.value?[el.value]:[];else r.report[el.name]=el.value}const result=(r.report.tespitSonucu||[])[0]||"";if(!["İşgalli","Kısmen işgalli"].includes(result)){r.report.kullanimAmaclari=[];r.report.kullanimAlani="";r.report.baslangicTarihi="";r.report.kullaniciAdi="";r.report.kullaniciKimlik="";r.report.kullaniciAdres="";if(r.saha){delete r.saha.occupationGeometry;delete r.saha.occupationAreaM2;delete r.saha.occupationPercent;delete r.saha.occupationMeasuredAt;delete r.saha.occupationMethod;delete r.saha.occupationAreaSynced}}r.saha={...(r.saha||{}),updatedAt:new Date().toISOString()};r.saha.revisit=$("#revisitRequired").checked?{required:true,reason:$("#revisitReason").value||"Diğer",at:new Date().toISOString()}:{required:false,reason:""};r.saha.officeTasks=[...document.querySelectorAll('[data-office-task]:checked')].map(x=>x.dataset.officeTask);r.saha.fieldNote=$('#parcelFieldNote')?.value?.trim()||'';r.saha.fieldNoteTags=[...document.querySelectorAll('[data-field-note-tag]:checked')].map(x=>x.dataset.fieldNoteTag);r.signature=$("#sig").dataset.value||r.signature||"";await save();renderEvidencePanel();return r}
function validate(r){const res=(r.report.tespitSonucu||[])[0],probs=[];if(!res)probs.push("Tespit sonucu");if((res==="İşgalli"||res==="Kısmen işgalli")&&!r.report.kullaniciAdi)probs.push("Kullanıcı/fuzuli şagil");if(res==="Kısmen işgalli"&&!r.report.kullanimAlani)probs.push("Kullanım alanı");if((res==="İşgalli"||res==="Kısmen işgalli")&&!(r.report.kullanimAmaclari||[])[0])probs.push("Kullanım amacı");const oa=occupationAssessment(occupationGeometry(r),geometry(current));if(occupationGeometry(r).length&&oa.self)probs.push("İşgal çizimi kendi kendini kesiyor");if(occupationGeometry(r).length&&(oa.outside||oa.edgeOutside||oa.over))probs.push("İşgal çizimi parsel dışına taşıyor");return probs}
function resultPayload(){if(!data.package)return null;const results=Object.values(data.records).filter(r=>r.status==="completed"||r.saha?.updatedAt||r.saha?.gps||(r.photos||[]).length||r.signature).map(r=>({propertyId:r.propertyId,key:r.key,status:r.status,report:r.report,saha:r.saha,photos:r.photos,signature:r.signature,history:r.history||[]}));const kmlUpdates=(data.package.properties||[]).filter(p=>p.kml?.mobileAddedAt&&geometry(p).length>=3).map(p=>({propertyId:p.id,key:p.key,il:p.il,ilce:p.ilce,mahalle:p.mahalle,ada:p.ada,parsel:p.parsel,zeminId:p.zeminId||'',tasinmazNo:p.tasinmazNo||'',geometry:geometry(p),kml:clonePlain(p.kml)||{}}));return{app:"METS_SAHA_SONUCLARI",schemaVersion:4,packageId:data.package.packageId,exportedAt:new Date().toISOString(),pwaVersion:APP_VERSION,results,kmlUpdates}}
