function compress(file){return new Promise((ok,no)=>{const img=new Image,fr=new FileReader;fr.onload=()=>{img.onload=()=>{const max=1600,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement("canvas");c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext("2d").drawImage(img,0,0,c.width,c.height);ok(c.toDataURL("image/jpeg",.7))};img.onerror=no;img.src=fr.result};fr.onerror=no;fr.readAsDataURL(file)})}
