const canvas=$("#sig"),ctx=canvas.getContext("2d");ctx.lineWidth=4;ctx.lineCap="round";let drawing=false;function pos(e){const r=canvas.getBoundingClientRect(),p=e.touches?e.touches[0]:e;return{x:(p.clientX-r.left)*canvas.width/r.width,y:(p.clientY-r.top)*canvas.height/r.height}}function start(e){drawing=true;const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y);e.preventDefault()}function move(e){if(!drawing)return;const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke();e.preventDefault()}function end(){if(!drawing)return;drawing=false;canvas.dataset.value=canvas.toDataURL("image/png")}function drawSavedSignature(){ctx.clearRect(0,0,canvas.width,canvas.height);const r=rec(current),src=r.signature||"";canvas.dataset.value=src;if(src){const im=new Image;im.onload=()=>ctx.drawImage(im,0,0,canvas.width,canvas.height);im.src=src}}
