// v0.13.1 — KML Hazırlık Merkezi
function kmlNormName(v){return normText(v).replace(/\b(MAHALLESİ|MAHALLESI|MAH\.?|M)\b/g,'').replace(/[^A-ZÇĞİÖŞÜ0-9]/g,'')}
function kmlFieldKey(v){return normText(v).replace(/[^A-ZÇĞİÖŞÜ0-9]/g,'')}
function kmlData(pm,...names){const wanted=new Set(names.map(kmlFieldKey));for(const d of pm.getElementsByTagName('Data')){if(wanted.has(kmlFieldKey(d.getAttribute('name')||''))){const v=d.getElementsByTagName('value')[0];return (v?.textContent||d.textContent||'').trim()}}return''}
function parseCoordinateText(txt){return String(txt||'').trim().split(/\s+/).map(s=>s.split(',')).filter(a=>a.length>=2&&Number.isFinite(Number(a[0]))&&Number.isFinite(Number(a[1]))).map(a=>[Number(a[0]),Number(a[1])])}
function parseKmlText(text,fileName=''){const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.querySelector('parsererror'))throw Error(`KML okunamadı: ${fileName||'dosya'}`);const rows=[];for(const pm of [...doc.getElementsByTagName('Placemark')]){const polygons=[...pm.getElementsByTagName('Polygon')];if(!polygons.length)continue;let best=[];for(const poly of polygons){const c=poly.getElementsByTagName('coordinates')[0];const pts=parseCoordinateText(c?.textContent||'');if(pts.length>=3&&pts.length>best.length)best=pts}if(best.length<3)continue;const pmName=(pm.getElementsByTagName('name')[0]?.textContent||'').trim();const nm=pmName.match(/(\d+)\s*[- ]?\s*ada\s*[- ]?\s*(\d+)\s*[- ]?\s*parsel/i);rows.push({takbisno:kmlData(pm,'takbisno','zeminid','zemin no','taşınmaz no','tasinmazno'),il:kmlData(pm,'idari_il_ad','il'),ilce:kmlData(pm,'idari_ilce_ad','ilçe','ilce'),mahalle:kmlData(pm,'idari_mahalle_ad','mahalle','mahallesi'),ada:kmlData(pm,'tapu_bilgileri_ada_no','ada')||nm?.[1]||'',parsel:kmlData(pm,'tapu_bilgileri_parsel_no','parsel','parselno','parsel no')||nm?.[2]||'',yuzolcumu:kmlData(pm,'yuzolcumu','yüzölçümü','alan'),cinsi:kmlData(pm,'tapucinsaciklama','nitelik','cinsi','tapu cinsi'),geometry:best,fileName})}return rows}
function kmlPropertyCandidates(row){const props=data.package?.properties||[],tak=String(row.takbisno||'').trim();if(tak){const exact=props.filter(p=>[p.zeminId,p.tasinmazNo].some(v=>String(v||'').trim()===tak));if(exact.length)return{items:exact,method:'takbisno'}}const ilce=kmlNormName(row.ilce),mah=kmlNormName(row.mahalle),ada=String(row.ada||'').trim(),parsel=String(row.parsel||'').trim();if(!parsel)return{items:[],method:''};let c=props.filter(p=>(!ilce||kmlNormName(p.ilce)===ilce)&&(!mah||kmlNormName(p.mahalle)===mah)&&String(p.parsel||'').trim()===parsel);if(ada)c=c.filter(p=>String(p.ada||'').trim()===ada);if(c.length===1)return{items:c,method:ada?'ilce-mahalle-ada-parsel':'ilce-mahalle-parsel'};return{items:c,method:ada?'ilce-mahalle-ada-parsel':'ilce-mahalle-parsel'}}
function applyKmlRow(row,p,method){const pts=row.geometry||[];if(pts.length<3)return{ok:false,reason:'geometri yok'};if(geometry(p).length&&p.kml?.status==='matched'&&!p.kml?.mobileAddedAt)return{ok:false,reason:'zaten güvenli KML var',skipped:true};const kmlArea=polygonAreaMeters(pts),takArea=parseArea(p.yuzolcumu),diff=takArea&&kmlArea?Math.abs(kmlArea-takArea)/takArea*100:null;const review=Number.isFinite(diff)&&diff>10;p.geometry=pts;p.kml={...(p.kml||{}),status:review?'review':'matched',message:review?`Mobil KML eklendi; TAKPAS alan farkı %${diff.toFixed(1)} — kontrol gerekli`:`Mobil KML güvenli eşleşti${Number.isFinite(diff)?` · alan farkı %${diff.toFixed(1)}`:''}`,candidateCount:1,invalidCount:0,matchMethod:`mobile-${method}`,sourceFile:row.fileName||'',source:'TKGM/MEGSİS manuel KML',mobileAddedAt:new Date().toISOString(),areaDifferencePercent:Number.isFinite(diff)?Number(diff.toFixed(2)):null,takbisno:row.takbisno||''};return{ok:true,review,diff}}
async function importKmlFiles(files,targetId=null){if(!data.package)return toast('Önce saha paketi yükleyin.');const report={at:new Date().toISOString(),files:files.length,placemarks:0,matched:0,review:0,unmatched:0,ambiguous:0,skipped:0,errors:[],targetId:targetId||''};for(const file of files){try{const rows=parseKmlText(await file.text(),file.name);report.placemarks+=rows.length;let targetFound=false;for(const row of rows){const found=kmlPropertyCandidates(row);let candidates=found.items;if(targetId)candidates=candidates.filter(p=>p.id===targetId);if(targetId&&candidates.length===1)targetFound=true;if(candidates.length===1){const r=applyKmlRow(row,candidates[0],found.method);if(r.ok){report.matched++;if(r.review)report.review++}else if(r.skipped)report.skipped++}else if(candidates.length>1)report.ambiguous++;else report.unmatched++}if(targetId&&!targetFound)report.errors.push(`${file.name}: seçili taşınmazla eşleşen parsel kaydı bulunamadı.`)}catch(e){report.errors.push(`${file.name}: ${e.message}`)}}lastKmlImportReport=report;data.meta={...(data.meta||{}),lastKmlImportReport:report};await save();render();const msg=`${report.files} dosya · ${report.placemarks} poligon · ${report.matched} eşleşti${report.review?` · ${report.review} kontrol`:''}${report.ambiguous?` · ${report.ambiguous} belirsiz`:''}${report.unmatched?` · ${report.unmatched} eşleşmedi`:''}`;toast(msg);return report}
function kmlPrepAnalysis(){const props=selectedNeighborhoodProps(),ready=props.filter(p=>geometry(p).length&&!kmlNeedsReview(p)).length,review=props.filter(kmlNeedsReview).length,missing=props.filter(p=>!geometry(p).length),mobile=props.filter(p=>p.kml?.mobileAddedAt).length;return{props,ready,review,missing,mobile}}
function renderKmlPrep(){const badge=$('#kmlPrepBadge'),stats=$('#kmlPrepStats'),list=$('#kmlMissingList'),rep=$('#kmlPrepReport');if(!badge||!stats||!list)return;const a=kmlPrepAnalysis();if(!a.props.length){badge.textContent='Mahalle seçin';stats.innerHTML='';list.innerHTML='<div class="muted">İlçe ve mahalle seçildiğinde KML eksikleri burada listelenir.</div>';rep.textContent='';return}badge.textContent=a.missing.length?`${a.missing.length} KML eksik`:'KML hazır';stats.innerHTML=`<div class="kml-prep-stat"><b>${a.ready}</b><small>Hazır</small></div><div class="kml-prep-stat"><b>${a.missing.length}</b><small>Eksik</small></div><div class="kml-prep-stat"><b>${a.review}</b><small>Kontrol</small></div>`;const r=data.meta?.lastKmlImportReport;rep.innerHTML=r?`Son KML işlemi: <b>${r.matched||0} eşleşti</b>${r.review?` · ${r.review} kontrol`:''}${r.unmatched?` · ${r.unmatched} eşleşmedi`:''}${r.ambiguous?` · ${r.ambiguous} belirsiz`:''}${r.errors?.length?` · ${r.errors.length} hata`:''}`:`Toplu mahalle KML dosyası da seçebilirsiniz. METS, aynı dosyanın içindeki birden çok parseli otomatik eşleştirebilir.`;if(!a.missing.length){list.innerHTML='<div class="kml-ready-note">✓ Seçili mahallede KML’siz taşınmaz kalmadı. Saha hazırlığı açısından geometri kapsamı tamam.</div>';return}list.innerHTML=a.missing.slice(0,80).map(p=>`<div class="kml-missing-row"><div><b>${esc(p.ada||'—')} ada ${esc(p.parsel||'—')} parsel</b><small>${esc(p.mahalle||'')} · ${esc(p.yuzolcumu||'—')} m² · Zemin/Taşınmaz No: ${esc(p.zeminId||p.tasinmazNo||'—')}</small></div><div class="kml-missing-actions"><button type="button" data-kml-tkgm="${esc(p.id)}" class="secondary">TKGM Aç</button><button type="button" data-kml-add="${esc(p.id)}" class="primary">KML Ekle</button></div></div>`).join('')+(a.missing.length>80?`<div class="muted">İlk 80 kayıt gösteriliyor. Toplam ${a.missing.length} KML eksik.</div>`:'');list.querySelectorAll('[data-kml-tkgm]').forEach(b=>b.onclick=()=>openTkgmForProperty(b.dataset.kmlTkgm));list.querySelectorAll('[data-kml-add]').forEach(b=>b.onclick=()=>{kmlSingleTargetId=b.dataset.kmlAdd;$('#kmlSingleInput').click()})}
async function openTkgmForProperty(id){const p=(data.package?.properties||[]).find(x=>x.id===id);const q=p?`${p.il||'Erzurum'} ${p.ilce||''} ${p.mahalle||''} ${p.ada||''} ada ${p.parsel||''} parsel`:'';if(q&&navigator.clipboard){try{await navigator.clipboard.writeText(q);toast('Parsel bilgisi panoya kopyalandı; TKGM ekranında aratabilirsiniz.')}catch{}}window.open('https://parselsorgu.tkgm.gov.tr/','_blank','noopener')}
