// v0.13 — Çevrimdışı Mahalle Paketi + Saha Hazırlık Merkezi
function selectedNeighborhoodKey(){const d=$("#districtSelect")?.value||"",m=$("#neighborhoodSelect")?.value||"";return d&&m?`${d}||${m}`:""}
function offlinePrepMeta(){data.meta=data.meta||{};data.meta.offlinePrepared=data.meta.offlinePrepared||{};return data.meta.offlinePrepared}
function currentOfflinePrep(){const k=selectedNeighborhoodKey();return k?offlinePrepMeta()[k]||null:null}
function prepAnalysis(){const props=selectedNeighborhoodProps(),st=neighborhoodStats(props),age=packageAgeDays(),review=props.filter(kmlNeedsReview).length,missing=props.filter(p=>!geometry(p).length).length,history=props.filter(p=>historyEntries(rec(p)).length).length,pending=props.filter(p=>rec(p).status!=="completed").length,prepared=currentOfflinePrep(),secure=!!window.isSecureContext,sw=!!navigator.serviceWorker,storage=!!window.indexedDB;let score=100,issues=[];if(!props.length)return{score:0,props,st,checks:[],issues:["Mahalle seçilmedi"],prepared};if(missing){score-=Math.min(30,Math.ceil(missing/props.length*30));issues.push(`${missing} taşınmazda KML yok`)}if(review){score-=Math.min(15,review*2);issues.push(`${review} KML kontrol gerekli`)}if(age!=null&&age>30){score-=15;issues.push(`Paket ${age} günlük`)}if(!secure){score-=20;issues.push("HTTPS değil")};if(!storage){score-=30;issues.push("Yerel depolama yok")};if(!sw){score-=10;issues.push("Servis çalışanı yok")};if(!prepared)score-=5;score=Math.max(0,Math.min(100,score));const checks=[
 {level:storage?'good':'bad',title:'Yerel veri deposu',detail:storage?'IndexedDB kullanılabilir':'Bu tarayıcı yerel depolamayı desteklemiyor'},
 {level:secure?'good':'bad',title:'Güvenli bağlantı',detail:secure?'HTTPS / güvenli bağlam aktif':'GPS, kamera ve PWA özellikleri kısıtlanabilir'},
 {level:sw?'good':'warn',title:'Uygulama çevrimdışı kabuğu',detail:sw?'Service Worker destekleniyor':'Tarayıcı çevrimdışı uygulama önbelleğini desteklemiyor'},
 {level:missing?'warn':'good',title:'KML kapsamı',detail:`${st.withGeom}/${st.total} taşınmazda geometri`},
 {level:review?'warn':'good',title:'KML kalite kontrolü',detail:review?`${review} kayıt kontrol bekliyor`:'Kontrol uyarısı yok'},
 {level:age!=null&&age>30?'warn':'good',title:'Paket güncelliği',detail:age==null?'Tarih bilinmiyor':`${age} günlük saha paketi`},
 {level:prepared?'good':'warn',title:'Mahalle hazırlık işareti',detail:prepared?`Hazırlandı: ${new Date(prepared.at).toLocaleString('tr-TR')}`:'Henüz çevrimdışı hazırlık yapılmadı'},
 {level:'good',title:'Çevrimdışı harita davranışı',detail:'İnternet yoksa uydu yerine KML krokisi kullanılır'}
];return{score,props,st,checks,issues,prepared,history,pending,age}}
function renderOfflinePrep(){const badge=$("#offlinePrepBadge"),scoreEl=$("#offlinePrepScore"),checks=$("#offlinePrepChecks"),info=$("#offlinePrepInfo"),a=prepAnalysis();if(!badge||!scoreEl||!checks)return;if(!a.props.length){badge.textContent='Mahalle seçin';scoreEl.innerHTML='<div class="muted">Hazırlık analizi için ilçe ve mahalle seçin.</div>';checks.innerHTML='';info.textContent='';return}badge.textContent=a.prepared?'Çevrimdışı hazır':`${a.score}% hazır`;const cls=a.score>=85?'ready':a.score>=60?'warn':'bad';scoreEl.innerHTML=`<div class="prep-big ${cls}"><b>%${a.score}</b><span>Saha hazırlık puanı</span></div><div><div class="prep-bar"><i style="width:${a.score}%"></i></div><div class="prep-desc">${a.st.total} taşınmaz · ${a.st.withGeom} KML'li · ${a.pending} açık saha kaydı · ${a.history} geçmişli kayıt</div></div>`;checks.innerHTML=a.checks.map(c=>`<div class="prep-check ${c.level}"><i>${c.level==='good'?'✓':c.level==='bad'?'!':'△'}</i><span><b>${esc(c.title)}</b><small>${esc(c.detail)}</small></span></div>`).join('');info.innerHTML=a.prepared?`Bu mahalle <b>${new Date(a.prepared.at).toLocaleString('tr-TR')}</b> tarihinde hazırlandı. Hazırlık anında ${a.prepared.count||a.st.total} taşınmaz ve ${a.prepared.withGeom||a.st.withGeom} KML geometrisi vardı.`:`Hazırlık yapıldığında uygulama kabuğu doğrulanır ve mahalle bu cihazda “sahaya hazır” olarak işaretlenir.`}
async function warmOfflineShell(){if(!('caches' in window))return{ok:false,count:0};const names=await caches.keys();let count=0;for(const n of names){const c=await caches.open(n);count+=(await c.keys()).length}return{ok:count>0,count,names}}
async function prepareNeighborhoodOffline(){const a=prepAnalysis(),key=selectedNeighborhoodKey();if(!key||!a.props.length)return toast('Önce ilçe ve mahalle seçin.');const shell=await warmOfflineShell();const meta=offlinePrepMeta();meta[key]={at:new Date().toISOString(),packageId:data.package?.packageId||'',count:a.st.total,withGeom:a.st.withGeom,missing:a.st.missing,review:a.st.review,appVersion:APP_VERSION,shellCached:shell.ok,shellEntries:shell.count};await save();renderOfflinePrep();toast(`Mahalle hazırlandı: ${a.st.total} taşınmaz · ${a.st.withGeom} KML. İnternet yoksa KML krokisi kullanılacak.`)}
