async function offlineSelfTest(){const a=prepAnalysis();if(!a.props.length)return toast('Önce ilçe ve mahalle seçin.');const shell=await warmOfflineShell();const failures=[];if(!window.indexedDB)failures.push('IndexedDB');if(!navigator.serviceWorker)failures.push('Service Worker');if(!shell.ok)failures.push('uygulama önbelleği');if(!a.st.withGeom)failures.push('KML geometrisi');const info=$("#offlinePrepInfo");if(failures.length){info.innerHTML=`<b>Çevrimdışı test: kontrol gerekli.</b> Eksik/şüpheli: ${failures.map(esc).join(', ')}. KML'siz kayıtlar listeden açılabilir ancak haritada gösterilemez.`;toast('Çevrimdışı hazırlıkta kontrol gereken noktalar var.')}else{info.innerHTML=`<b>Çevrimdışı test geçti.</b> Yerel veri deposu açık, uygulama kabuğunda ${shell.count} önbellek girdisi var ve mahallede ${a.st.withGeom} KML geometrisi mevcut. Uydu altlığı internet yokken gösterilmeyecek; KML krokisi devreye girecek.`;toast('Çevrimdışı hazırlık testi geçti.')}}
