function incompleteNeighborhoodProps(){return selectedNeighborhoodProps().filter(p=>rec(p).status!=='completed'&&geometry(p).length)}
function estimateMinutesForProperty(p,from){const r=rec(p),g=geometry(p),c=centroid(g);let travel=0;if(from&&c)travel=Math.min(25,Math.max(1,haversine(from.lat,from.lon,c[1],c[0])/1000*3.2));let work=8;if(revisitInfo(r))work+=5;if(kmlNeedsReview(p))work+=4;if(historyEntries(r).length)work+=2;return Math.round(travel+work)}
function buildDayPlan(){const mins=Number($('#dayPlanMinutes')?.value||180),g=lastGps();let props=incompleteNeighborhoodProps();if(!props.length){$('#dayPlanResult').innerHTML='Bu mahallede planlanacak açık KML’li parsel yok.';return}let pos=g?{lat:g.lat,lon:g.lon}:null,used=0,rows=[];while(props.length&&used<mins){props.sort((a,b)=>{if(!pos)return String(a.ada).localeCompare(String(b.ada),'tr',{numeric:true})||String(a.parsel).localeCompare(String(b.parsel),'tr',{numeric:true});const ca=centroid(geometry(a)),cb=centroid(geometry(b));return haversine(pos.lat,pos.lon,ca[1],ca[0])-haversine(pos.lat,pos.lon,cb[1],cb[0])});const p=props.shift(),m=estimateMinutesForProperty(p,pos);if(rows.length&&used+m>mins)break;used+=m;rows.push({p,m});const c=centroid(geometry(p));if(c)pos={lat:c[1],lon:c[0]}}$('#dayPlanResult').innerHTML=`<b>${rows.length} parsel · yaklaşık ${used} dk</b>`+rows.map((x,i)=>`<div class="day-plan-row"><span>${i+1}. ${esc(x.p.ada||'—')}/${esc(x.p.parsel||'—')}</span><small>~${x.m} dk</small></div>`).join('')+`<small class="muted">Süreler saha planlama tahminidir; yol ve tespit koşullarına göre değişebilir.</small>`}
