async function initBattery(){const el=$('#batteryStatus');if(!el)return;try{if(navigator.getBattery){batteryInfo=await navigator.getBattery();const draw=()=>{el.textContent=`Pil: %${Math.round(batteryInfo.level*100)}${batteryInfo.charging?' · şarj oluyor':''}${batteryInfo.level<.25&&!batteryInfo.charging?' · düşük pil':''}`};draw();batteryInfo.addEventListener('levelchange',draw);batteryInfo.addEventListener('chargingchange',draw)}else el.textContent='Pil seviyesi tarayıcı tarafından paylaşılmıyor.'}catch{el.textContent='Pil bilgisi alınamadı.'}}
function renderResume(){const box=$('#resumeBox');if(!box)return;const id=data.meta?.lastOpenPropertyId,p=data.package?.properties?.find(x=>x.id===id);if(!p||rec(p).status==='completed'){box.hidden=true;return}box.hidden=false;box.innerHTML=`<b>↩ Son açık tespit</b><span>${esc(p.mahalle||'')} · ${esc(p.ada||'—')} ada ${esc(p.parsel||'—')} parsel</span><div class="resume-actions"><button type="button" id="resumeLastBtn" class="secondary">Kaldığım Yerden Devam Et</button></div>`;$('#resumeLastBtn').onclick=()=>open(p.id)}
function renderSmartOps(){renderResume();const t=$('#batterySaverToggle');if(t)t.checked=batterySaverEnabled();const b=$('#smartOpsBadge');if(b)b.textContent=batterySaverEnabled()?'Pil koruma':'Hazır'}
