document.querySelectorAll('[data-quick-use]').forEach(b=>b.onclick=()=>{const f=$('#form'),v=b.dataset.quickUse;if(!['İşgalli','Kısmen işgalli'].includes(f.elements.tespitSonucu.value)){f.elements.tespitSonucu.value='İşgalli';applyDynamicForm()}f.elements.kullanimAmaclari.value=v;renderEvidencePanel();renderPhotoGuide();toast(`${v} kullanım amacı seçildi.`)});
