$('#neighborhoodCloseBtn').onclick=()=>{const props=selectedNeighborhoodProps();if(!props.length)return toast('Önce ilçe ve mahalle seçin.');let pending=0,revisit=0,evidence=0,unexp=0,missingKml=0;for(const p of props){const r=rec(p);if(r.status!=='completed')pending++;if(revisitInfo(r))revisit++;if(r.status==='draft'){const e=completionAssessment(r,p);if(e.critical.length||e.warn.length)evidence++}if(isUnexported(r))unexp++;if(!geometry(p).length)missingKml++}const issues=[];if(pending)issues.push(`${pending} tamamlanmamış`);if(revisit)issues.push(`${revisit} tekrar ziyaret`);if(evidence)issues.push(`${evidence} taslakta eksik/uyarı`);if(unexp)issues.push(`${unexp} aktarılmamış`);if(missingKml)issues.push(`${missingKml} KML eksik`);const out=$('#neighborhoodCloseReport');out.className=`neighborhood-close-report ${issues.length?'warn':'ready'}`;out.innerHTML=issues.length?`<b>Mahalleden ayrılmadan kontrol edin</b><span>${issues.map(esc).join(' · ')}</span>`:`<b>✓ Mahalle kapanış kontrolü temiz</b><span>Tamamlanmamış, tekrar ziyaret veya aktarım uyarısı görünmüyor.</span>`;toast(issues.length?'Kapanışta kontrol gereken işler var.':'Mahalle kapanış kontrolü temiz.')};
