$("#back").onclick=async()=>{occupationDrawing=false;occupationDraft=[];document.body.classList.remove('occupation-draw-active');if(watchId!==null){navigator.geolocation.clearWatch(watchId);watchId=null;$("#trackBtn").textContent="Canlı Takip Başlat"}await collect();data.meta={...(data.meta||{}),lastEditorClosedAt:new Date().toISOString()};await save();$("#editor").hidden=true;$("#home").hidden=false;render();renderSmartOps()};
