$("#complete").onclick=async()=>{const r=await collect(),c=completionAssessment(r,current),rv=revisitInfo(r);if(c.critical.length&&!rv)return toast(`Tamamlanamadı: ${c.critical.join(", ")}. Eksik giderilemiyorsa “tekrar gidilecek” olarak işaretleyin.`);if(c.warn.length&&!rv&&!confirm(`Tamamlama kontrolünde uyarılar var: ${c.warn.join(", ")}. Yine de tamamlandı işaretlensin mi?`))return;r.status="completed";r.saha={...(r.saha||{}),completedAt:new Date().toISOString(),evidence:{score:c.score,label:c.label,missing:c.critical,warn:c.warn},completionCheck:{score:c.score,label:c.label,critical:c.critical,warn:c.warn,at:new Date().toISOString()}};await addHistorySnapshot(r);const g=lastGps(),next=g?nearestIncomplete(g):null;if(next)data.meta={...(data.meta||{}),nextSuggestion:{id:next.p.id,distance:next.distance,at:new Date().toISOString()}};await save();if(liveState().active){await advanceLiveTarget(true);const lp=liveTarget();toast(lp?`Tespit tamamlandı. Canlı Saha yeni hedefi hazırladı: ${lp.ada||"—"}/${lp.parsel||"—"}.`:`Tespit tamamlandı. Seçili mahallede açık KML’li hedef kalmadı.`)}else toast(next?`Tespit tamamlandı. Sıradaki en yakın parsel yaklaşık ${next.distance<1000?Math.round(next.distance)+" m":(next.distance/1000).toFixed(2)+" km"}.` : "Tespit tamamlandı.");setTimeout(()=>$("#back").click(),650)};
async function acceptGpsPosition(p,live=false){if(!current)return;const r=rec(current),gps={lat:p.coords.latitude,lon:p.coords.longitude,accuracy:p.coords.accuracy,altitude:p.coords.altitude,heading:p.coords.heading,speed:p.coords.speed,at:new Date().toISOString()};r.saha={...(r.saha||{}),gps};data.meta={...(data.meta||{}),lastGps:{lat:gps.lat,lon:gps.lon,accuracy:gps.accuracy,at:gps.at}};await save();$("#gpsText").textContent=`${p.coords.latitude.toFixed(6)}, ${p.coords.longitude.toFixed(6)} · ±${Math.round(p.coords.accuracy)} m${live?" · canlı":""}`;updateGpsQuality(gps);renderParcelMap();renderEvidencePanel()}

