$("#gpsBtn").onclick=()=>{if(!window.isSecureContext)return toast("GPS için uygulamayı HTTPS üzerinden açın.");if(!navigator.geolocation)return toast("Bu cihaz konum erişimini desteklemiyor.");$("#gpsText").textContent="Konum alınıyor…";navigator.geolocation.getCurrentPosition(async p=>{await acceptGpsPosition(p,false);toast("Konum kaydedildi ve parsel mesafesi hesaplandı.")},e=>{toast("Konum alınamadı: "+e.message);$("#gpsText").textContent="Konum alınamadı."},geoOptions(false))};
$("#trackBtn").onclick=()=>{if(!window.isSecureContext)return toast("Canlı GPS için uygulamayı HTTPS üzerinden açın.");if(!navigator.geolocation)return toast("Bu cihaz konum erişimini desteklemiyor.");if(watchId!==null){navigator.geolocation.clearWatch(watchId);watchId=null;$("#trackBtn").textContent="Canlı Takip Başlat";toast("Canlı takip durduruldu.");return}$("#trackBtn").textContent="Canlı Takibi Durdur";watchId=navigator.geolocation.watchPosition(p=>acceptGpsPosition(p,true).catch(console.error),e=>toast("Canlı konum alınamadı: "+e.message),geoOptions(true));toast("Canlı parsel takibi başladı.")};
