$("#entryBtn").onclick=async()=>{if(!current)return;try{const g=userGps()||lastGps()||await acquireNeighborhoodGps(false);const pts=geometry(current),dist=pts.length?distanceToPolygonMeters(g.lon,g.lat,pts):null;if(Number.isFinite(dist)&&dist>250&&!confirm(`Konum parsel sınırından yaklaşık ${Math.round(dist)} m uzakta. Yine de giriş noktası olarak kaydedilsin mi?`))return;const r=rec(current);r.saha={...(r.saha||{}),entryPoint:{lat:g.lat,lon:g.lon,accuracy:g.accuracy||0,at:new Date().toISOString()}};await save();renderEntryInfo();toast("Parsel giriş noktası kaydedildi.")}catch(e){toast(e.message)}};
$("#photoInput").onchange=async e=>{const r=rec(current),type=$("#photoTypeSelect")?.value||"Diğer";const g=r.saha?.gps||lastGps(),pts=geometry(current);if(g&&pts.length){const d=distanceToPolygonMeters(g.lon,g.lat,pts),limit=Math.max(80,Number(g.accuracy||0)+50);if(Number.isFinite(d)&&d>limit&&!confirm(`Fotoğraf konumu seçili parsel sınırından yaklaşık ${Math.round(d)} m uzakta görünüyor (GPS ±${Math.round(g.accuracy||0)} m). Yanlış parselde olabilirsiniz. Yine de fotoğraf eklensin mi?`)){e.target.value="";toast("Fotoğraf eklenmedi: konum seçili parselden uzak.");return}}for(const f of [...e.target.files]){if(r.photos.length>=MAX_PHOTOS)break;try{const src=await compress(f),g=r.saha?.gps||lastGps(),q=await analyzeImageQuality(src);r.photos.push(src);photoMeta(r).push({type,at:new Date().toISOString(),gps:g?{lat:g.lat,lon:g.lon,accuracy:g.accuracy||0}:null,heading:Number.isFinite(radarHeading)?Number(radarHeading):null,quality:q})}catch{}}try{await save()}catch(err){toast("Fotoğraf kaydedilemedi. Cihaz depolamasını/yedeği kontrol edin.");console.error(err)}renderPhotos();renderEvidencePanel();renderHistory();e.target.value="";const warns=photoMeta(r).filter(x=>x?.quality?.level==='warn').length;toast(`${r.photos.length} fotoğraf kaydedildi${warns?` · ${warns} kalite uyarısı`:''}.`)};
